  "cal.methodFactorK": "<b>Methodenfaktor k.</b> Amtliche Fahrten je E-Scooter und Tag in Berlin (gleiches Quartal, sonst Vorjahresquartal, sonst jüngstes) ÷ unsere Berliner Messung über die letzten bis zu {CALIB_DAYS} Tagesdateien (ab {minDays} vollen Tagen mit demselben Regelstand nur diese); k gleicht verschluckte Fahrten zwischen zwei Abrufen und Kennungswechsel aus und gilt nur für E-Scooter derselben Kennungsart wie die Berliner Referenz, nicht für stabile oder periodisch wechselnde Kennungen; die Spanne folgt aus dem kleinsten und größten Quartalswert.",
