  "app.dataagemin": "Datenalter_min",
  // Einsammelliste: Fahrzeuge im eigenen Abstellverbot (web/ops.js, lib/pulse-ops.js parkingViolations)
  "col.title": "Einsammelliste: falsch abgestellt in eigenen Zonen",
  "col.csvTitle": "Einsammelliste als CSV (Semikolon; Art, Lage, Zone, Stationsabstand, Standzeit, Ladestand, Reichweite)",
  "col.file": "einsammeln-abstellverbot",
  "col.zoneId": "Zone {id}",
  "col.kindNoRide": "Fahrverbot",
  "col.kindNoPark": "Abstellverbot",
  "col.kindMpz": "Pflicht-Abstellzone ohne Station",
  "col.kindZone": "Art · Zone",
  "col.stationDist": "nächste eigene Station {m} m",
  "col.stationNone": "keine eigene Station ≤ {km} km",
  "col.method": "Intern, kein Anbieter-Vergleich. Geprüft werden verfügbare Fahrzeuge (nicht gesperrt, nicht reserviert) der gewählten Flotte gegen die eigenen GBFS-Geofencing-Zonen des Anbieters, in zwei Arten. Abstellverbot: Fahrtende, Fahrt oder Durchfahrt verboten; ausgenommen sind Pflicht-Abstellzonen, erlaubte Flächen in der Verbotszone, die kleiner sind als diese (z. B. ein Mobility Hub; ein Betriebsgebiet hebt nichts auf), und Fahrzeuge ≤ {stationM} m von einer eigenen Station. Pflicht-Abstellzone ohne Station: Zone mit station_parking (Abstellen nur an Stationen) und keine eigene Station ≤ {mpzStationM} m ({stationM} m Stationsabstand + GPS-Umfeld); {stationM}–{mpzStationM} m gilt als knapp neben der Station und wird nur gezählt. Gelistet wird ein Fahrzeug nur, wenn auch die 4 Punkte im Abstand von {buffers} m (Nord, Ost, Süd, West) im Verbot bzw. in einer Pflicht-Abstellzone liegen: so fallen GPS-Ungenauigkeit und Fahrzeuge am Zonenrand weg. Grenzen: Regeln je Fahrzeugtyp enthält der Datenstand nicht; eine Zone kann jünger sein als das Abstellen; Standzeiten ab Messbeginn sind Untergrenzen (≥).",
  "col.sub": "{op} in {muni} · Flotte vom {at} · Zonen aus dem Datenstand (GBFS)",
  "col.noFleet": "Noch keine Flotte gewählt: Gemeinde und Flotte oben wählen.",
  "col.loading": "Zonen werden geladen und geprüft …",
  "col.failed": "Zonen nicht geladen – Einsammelliste nicht geprüft.",
  "col.noZones": "Anbieter veröffentlicht keine Zonen ({op}, diese Gemeinde) – keine Prüfung möglich.",
  "col.head": "{n} Fahrzeuge einsammeln (geprüft mit {buffers} m Umfeld): {ban} im eigenen Abstellverbot (roh {raw}) · {mpz} in Pflicht-Abstellzone ohne Station (roh {mraw}; knapp neben Station {stationM}–{mpzStationM} m: {near})",
  "col.headOne": "{n} Fahrzeug einsammeln (geprüft mit {buffers} m Umfeld): {ban} im eigenen Abstellverbot (roh {raw}) · {mpz} in Pflicht-Abstellzone ohne Station (roh {mraw}; knapp neben Station {stationM}–{mpzStationM} m: {near})",
  "col.counts": "{available} verfügbare Fahrzeuge geprüft · Abstellverbot: Koordinate in eigener Verbotszone {inZone}, davon ausgenommen: Pflicht-Abstellzone {mpz}, kleinere erlaubte Fläche {allowed}, eigene Station ≤ {stationM} m {station} · roh {raw} · robust je Umfeld {robust}",
  "col.countsMpz": "Pflicht-Abstellzone (Abstellen nur an Stationen): Koordinate in eigener Zone {inZone}, davon kleinere erlaubte Fläche {allowed}, eigene Station ≤ {stationM} m {station}, knapp neben Station ({stationM}–{mpzStationM} m) {near} · roh (keine Station ≤ {mpzStationM} m) {raw} · robust je Umfeld {robust}",
  "col.zonesLine": "{ban} Verbots- und {mpzZones} Pflicht-Abstellzonen aus {files} Zonen-Feed(s)",
