  "fv.nScopeOf": "Gezeigt für: {s}.",
  "fv.modelTitle": "Modell",
  "fv.modelSub": "Poisson-Regression über alle Gruppen gemeinsam („gepoolt“), jeden Tag neu gelernt – dazu ein lernendes Modell, das je Gruppe aus den eigenen Fehlern gewichtet.",
  "fv.formula": "Fahrtbeginne je Gruppe und Stunde ~ Poisson(μ)\nlog μ = log(Fahrzeugstunden) + a[Gruppe] + Stunde[24] + Tagtyp × Stunde + Regelstand + Wetter (kalt, warm, Regen)\nlernend: Prognose = w[Gruppe] × eigenes Profil + (1 − w[Gruppe]) × gepoolt, w aus den eigenen Fehlern der Gruppe",
  "fv.mProfile": "Eigenes Stundenprofil je Gruppe und Tagtyp ohne Austausch zwischen Gruppen; stark bei viel Historie, schwach bei kleinen Gruppen.",
  "fv.mPooled": "Alle Gruppen gemeinsam: gemeinsame Tages- und Wochenform, nur das Niveau je Gruppe ist eigen; kommt auch mit kleinen Gruppen zurecht.",
  "fv.mPooledWx": "Wie gepoolt, dazu Temperatur (kalt/warm) und Regen; nur, wenn das Wetter-Gate offen ist und die Selbstprüfung messbar besser wird.",
  "fv.mNaive": "Messlatte, nicht wählbar: dieselbe Gruppe und Stunde am Vortag.",
  "fv.chooseRule": "Wahl: das Modell mit der kleinsten Wertung über die letzten {win} Tage (Wertung = Mittel aus Abweichung je Gruppe und Tag und je Gruppe und Stunde); das Wettermodell nur, wenn es mindestens {gain} besser ist als gepoolt; das lernende Modell nur, wenn es das so gewählte über dieselben Tage um mindestens {again} schlägt. Eine Wahl braucht {min} geprüfte Tage, bis dahin gilt gepoolt vorläufig. „Wie gestern“ wird nur verglichen, nie gewählt.",
  "fv.reasonNow": "Begründung des Sammlers:",
  "fv.assumeTitle": "Gemessen, abgeleitet, modelliert, vermutet",
  "fv.assumeSub": "Jede Größe, die in Prognose und Spot-Bewertung eingeht oder daraus entsteht – und wie belastbar sie ist.",
