  "cal.methodFactorK": "<b>Method factor k.</b> Official trips per e-scooter and day in Berlin (same quarter, otherwise the same quarter of the previous year, otherwise the latest) ÷ our Berlin measurement over the last up to {CALIB_DAYS} daily files (from {minDays} full days with the same rule version only those); k compensates for trips swallowed between two fetches and for ID rotation and only applies to e-scooters with the same ID type as the Berlin reference, not to stable or periodically rotating IDs; the range follows from the smallest and largest quarterly value.",
