  "cal.ruleRelease": "Release: k only takes effect once data/reference.json → kalibrierung.freigabe names the rule version of the Berlin measurement and {minDays} full measurement days with it exist; only for e-scooters with the same ID type as the reference ({v2}). Status: {v1}",
