  "app.tripDurationAvgEScooterTrip": "<b>Trip duration.</b> Avg. e-scooter trip = mean of the Berlin quarterly values{v0}; measured duration (20-min grid) applies only below that. Bikes, e-bikes, cargo bikes: no official evidence, previous assumptions.",
  "app.methodFactorKOfficialTrips": "<b>Method factor k.</b> Official trips per e-scooter and day in Berlin (same quarter, otherwise the same quarter of the previous year, otherwise the latest) ÷ our Berlin measurement over the last up to {CALIB_DAYS} daily files; k compensates for trips swallowed between two fetches and for ID rotation and applies to e-scooters nationwide, the range follows from the smallest and largest quarterly value.",
  "app.plausibilityIfOperatorS": "<b>Plausibility.</b> If an operator's measured trips per e-scooter and day in an area exceed {v0} ({overFactor} × largest Berlin quarterly value), it counts as an overcount: no calibration, not in totals. k comes only from plausible Berlin operators{v2}{v3}.",
  "app.preliminaryBelowMeasurement": "<b>Preliminary</b> below {minDays} measurement days or below {v1} % of observed hours of the day; without a Berlin measurement or with k outside {kMin}–{kMax} no calibration. An own “Correction ×” replaces k per operator.",
  "app.coverageAndCheckOwnEScooters": "<b>Coverage and check.</b> Own e-scooters ÷ official fleet: in Berlin the share of the licensed fleet (lower bound of feed coverage, not all licensed vehicles are on the street), in Munich of the active fleet; Frankfurt (lower bound from annual trips and fleet cap), Europe and Voi serve only for comparison.",
