  "col.head": "{n} vehicles to collect (checked with {buffers} m surroundings): {ban} in own no-parking zones (raw {raw}) · {mpz} in mandatory parking zones without station (raw {mraw}; just next to a station {stationM}–{mpzStationM} m: {near})",
  "col.headOne": "{n} vehicle to collect (checked with {buffers} m surroundings): {ban} in own no-parking zones (raw {raw}) · {mpz} in mandatory parking zones without station (raw {mraw}; just next to a station {stationM}–{mpzStationM} m: {near})",
  "col.counts": "{available} available vehicles checked · no-parking: coordinate in own no-parking zone {inZone}, of which excluded: mandatory parking zone {mpz}, smaller permitted area {allowed}, own station ≤ {stationM} m {station} · raw {raw} · robust per surroundings {robust}",
  "col.countsMpz": "Mandatory parking zone (parking only at stations): coordinate in own zone {inZone}, of which smaller permitted area {allowed}, own station ≤ {stationM} m {station}, just next to a station ({stationM}–{mpzStationM} m) {near} · raw (no station ≤ {mpzStationM} m) {raw} · robust per surroundings {robust}",
  "col.zonesLine": "{ban} no-parking/no-riding and {mpzZones} mandatory parking zones from {files} zone feed(s)",
