  "spots.method": "<b>Method:</b> a spot belongs to a place if the place’s centre is at most {r} m away; the densest places form first. Demand = trip starts of all operators per measured hour in the cell ({CELL}; {days} days, {h} h) ÷ 95th percentile of the municipality’s cells ({p95}/h), at most 1. Own vehicles without spot ÷ {g}, at most 1. Duplicates: own spots closer than {d} m; the one with the lowest empty rate stays.",
